from solution import recursive_list_sum


def test_if_isinstance_true_then_recursive_call():
    # Ensure the if branch (element is list) is taken and recursive call happens
    assert recursive_list_sum([[1, 2], 3]) == 6


def test_if_isinstance_false_then_add_element():
    # Ensure the else branch (element not list) is taken and element added
    assert recursive_list_sum([4, [5, 6]]) == 15


def test_recursive_call_then_loop_then_return():
    # Ensure recursive call occurs, then loop continues, then return total
    assert recursive_list_sum([1, [2, [3, 4]], 5]) == 15


def test_recursive_call_then_loop_then_if_false():
    # Ensure recursive call, then loop, then if condition false (non-list)
    assert recursive_list_sum([7, [8, 9]]) == 24


def test_if_true_then_loop_then_return():
    # Ensure if true (list), then loop continues, then return total
    assert recursive_list_sum([[1, 2], 3, 4]) == 10


def test_if_false_then_loop_then_if_true():
    # Ensure if false (non-list), then loop, then if true (list) in next iteration
    assert recursive_list_sum([5, [6, 7]]) == 18


def test_if_true_then_recursive_call_then_loop():
    # Ensure if true, recursive call, then loop continues
    assert recursive_list_sum([[1, 2], [3, 4], 5]) == 15


def test_if_true_then_recursive_call_then_return():
    # Ensure if true, recursive call, then return total after loop
    assert recursive_list_sum([[1, 2], 3]) == 6


def test_if_false_then_add_element_then_if_true():
    # Ensure if false (add element), then next iteration if true (list)
    assert recursive_list_sum([10, [11, 12]]) == 33


def test_if_false_then_add_element_then_if_false():
    # Ensure if false (add element), then next iteration if false (add element)
    assert recursive_list_sum([13, 14]) == 27


def test_if_true_then_recursive_call_then_if_false():
    # Ensure if true (list), recursive call, then next iteration if false (add element)
    assert recursive_list_sum([[15, 16], 17]) == 48


def test_if_true_then_recursive_call_then_if_true():
    # Ensure if true (list), recursive call, then next iteration if true (list)
    assert recursive_list_sum([[18, 19], [20, 21]]) == 78
